const TableEntry* Table(size_t& count) {
  count = sizeof(kEntries) / sizeof(kEntries[0]);
  return kEntries;
}

const uint32_t* TableSkins(const TableEntry& entry) { return kSkins + entry.firstSkin; }

const TableOptions* TableExtra(const TableEntry& entry) { return entry.options < 0 ? nullptr : kOptions + entry.options; }

